// HC-SR04 on D9 (trig) / D10 (echo). LED on D3 lights when something is within 100 cm.
const int TRIG = 9, ECHO = 10, LED = 3;

float readCm() {
  digitalWrite(TRIG, LOW);
  delayMicroseconds(2);
  digitalWrite(TRIG, HIGH);
  delayMicroseconds(10);
  digitalWrite(TRIG, LOW);
  long us = pulseIn(ECHO, HIGH, 30000);
  return us == 0 ? -1 : us * 0.0343 / 2.0;
}

void setup() {
  Serial.begin(9600);
  pinMode(TRIG, OUTPUT);
  pinMode(ECHO, INPUT);
  pinMode(LED, OUTPUT);
}

void loop() {
  float cm = readCm();
  digitalWrite(LED, cm >= 0 && cm <= 100 ? HIGH : LOW);
  Serial.print("distance: ");
  Serial.print(cm, 1);
  Serial.println(" cm");
  delay(300);
}
